const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const seattle = ee.Geometry.Point([-122.3321, 47.6062]);
  const startDate = '2021-09-01';
  const endDate = '2021-12-01';

  // 2. Data Acquisition & Check
  // Using GPM IMERG Final - precipitation rate in mm/hr
  let precipCol = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .select('precipitation')
    .filterDate(startDate, endDate)
    .filterBounds(seattle);

  const colSize = precipCol.size().getInfo();
  console.log(`GPM Images found: ${colSize}`);

  if (colSize === 0) {
    console.log("No precipitation data found for Seattle Sep-Nov 2021.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation over time
  // GPM provides precipitation in mm/hr at 30-min intervals
  // Need to multiply by 0.5 hours to get mm per image, then sum
  const totalPrecip = precipCol.map(function(img) {
    return img.multiply(0.5); // Convert mm/hr to mm per 30-min interval
  }).sum();

  // 4. Calculate total precipitation
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: seattle,
    scale: 10000,
    maxPixels: 1e9
  });

  const precipMm = stats.get('precipitation').getInfo();

  // Check pixel count
  const countStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: seattle,
    scale: 10000,
    maxPixels: 1e9
  });

  const pixelCount = countStats.get('precipitation').getInfo();

  if (pixelCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  if (precipMm === null || precipMm === undefined || isNaN(precipMm)) {
    console.log("Calculation failed - invalid result.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (precipMm < 0 || precipMm > 2000) {
    console.log(`Unrealistic precipitation value: ${precipMm}mm`);
    console.log("<answer>C3</answer>");
    return;
  }

  const precipCm = precipMm / 10;
  console.log(`Total precipitation Sep-Nov 2021: ${precipMm.toFixed(1)}mm (${precipCm.toFixed(1)}cm)`);
  console.log(`Valid pixels: ${pixelCount}`);
  console.log(`Images processed: ${colSize}`);

  if (precipCm >= 40) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
